import{_ as e,o as d,c as o,a3 as a}from"./chunks/framework.CWSmAuPU.js";const u=JSON.parse('{"title":"分阶段执行与提测","description":"","frontmatter":{},"headers":[],"relativePath":"guide/phases.md","filePath":"guide/phases.md","lastUpdated":1791966569000}'),s={name:"guide/phases.md"};function i(r,t,n,l,c,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="分阶段执行与提测" tabindex="-1">分阶段执行与提测 <a class="header-anchor" href="#分阶段执行与提测" aria-label="Permalink to &quot;分阶段执行与提测&quot;">​</a></h1><p>研发和测试常常是两拨人、两个节奏：研发完成要&quot;提测&quot;，测试同事先部署测试环境、准备数据，再验证，或者干脆人工测试。req-kit 把第 3–11 步分成<strong>研发</strong>和<strong>测试验证</strong>两个阶段，中间一个闸口。</p><h2 id="三种执行方式" tabindex="-1">三种执行方式 <a class="header-anchor" href="#三种执行方式" aria-label="Permalink to &quot;三种执行方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>执行方式</th><th>研发完成时</th><th>适合</th></tr></thead><tbody><tr><td><strong>连续</strong>（默认）</td><td>写好提测说明后直接进入测试验证</td><td>本地就能验证的项目</td></tr><tr><td><strong>分阶段</strong></td><td>停下来通知&quot;研发完成，可以提测&quot;，等人说&quot;开始测试验证&quot;或到预约的时间</td><td>有专门测试、需要先部署测试环境</td></tr><tr><td><strong>只做研发</strong></td><td>写提测说明和研发报告后结束，测试由人完成</td><td>测试必须由人完成</td></tr></tbody></table><p>标准档的需求在确定档位时，<code>/req</code> 会问执行方式（项目配置里定好了就不问），写进需求说明头部：<code>- 执行方式：分阶段</code>。团队可以在项目配置中统一设置：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;phases&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;mode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gated&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span></code></pre></div><h2 id="提测说明" tabindex="-1">提测说明 <a class="header-anchor" href="#提测说明" aria-label="Permalink to &quot;提测说明&quot;">​</a></h2><p>研发阶段的最后一步写 <code>handoff.md</code>，三种方式都写：</p><ol><li>这次改了什么（按功能需求列出，附分支和提交范围）</li><li>怎么跑起来（依赖、迁移、配置项、启动命令）</li><li>自测结果（测试、代码评审结论、哪些验收标准已有自动化测试）</li><li>建议重点测试（风险最高的验收标准、回归范围）</li><li>已知问题和未完成项</li><li>测试需要的准备（数据、账号、开关——只写在哪里取，不写口令）</li></ol><h2 id="开始测试验证" tabindex="-1">开始测试验证 <a class="header-anchor" href="#开始测试验证" aria-label="Permalink to &quot;开始测试验证&quot;">​</a></h2><p>收到&quot;研发完成，可以提测&quot;后，在对话中说&quot;开始测试验证&quot;。AI 会讲一遍提测说明，然后确定：</p><ul><li><strong>在哪里验证</strong>：本地启动服务，或<strong>已部署的测试环境</strong>。后者需要和你一起写 <code>test-env.md</code>（地址、如何确认被测版本、账号和口令从哪里取、可用的测试数据）。</li><li><strong>发现缺陷怎么办</strong>：当场修复并复验；<strong>退回研发</strong>（只记录缺陷，回到研发阶段修复、经过代码评审后重新提测）；或只记录。</li></ul><p>也可以预约：启动时加 <code>--verify-at 22:00</code>，研发完成后到时自动开始；或在开始命令后加 <code>--at</code>。</p><h2 id="测试同事接手" tabindex="-1">测试同事接手 <a class="header-anchor" href="#测试同事接手" aria-label="Permalink to &quot;测试同事接手&quot;">​</a></h2><p>用&quot;开发时自动新建工作区&quot;开发的需求，研发完成后，测试同事可以在这个项目<strong>任何工作区</strong>的对话中输入：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/req 开始测试验证 sms-login</span></span></code></pre></div><p>之后的通知发到测试同事的对话，步骤仍在需求自己的工作区中运行。研发阶段仍然只能从发起的对话操作。</p><h2 id="相关配置" tabindex="-1">相关配置 <a class="header-anchor" href="#相关配置" aria-label="Permalink to &quot;相关配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置</th><th>默认</th><th>作用</th></tr></thead><tbody><tr><td><code>phases.mode</code></td><td><code>continuous</code></td><td>执行方式：<code>continuous</code> / <code>gated</code> / <code>develop-only</code></td></tr><tr><td><code>phases.verify.environment</code></td><td><code>local</code></td><td><code>deployed</code>：对已部署的测试环境验证</td></tr><tr><td><code>phases.verify.agents</code></td><td><code>{}</code></td><td>测试阶段用的 agent，例如 <code>{ &quot;reviewer&quot;: { &quot;paseoProfile&quot;: &quot;测试&quot; } }</code></td></tr><tr><td><code>phases.verify.defects</code></td><td><code>fix</code></td><td><code>fix</code> / <code>handback</code> / <code>report</code></td></tr><tr><td><code>phases.verify.serviceStart</code></td><td><code>null</code></td><td>测试阶段是否做服务启动验证；<code>null</code> 按档位</td></tr></tbody></table><p>设计决定见 <a href="/paseo-req-kit/reference/adr/0022-develop-and-verify-phases">ADR 0022</a>。</p>',20)])])}const g=e(s,[["render",i]]);export{u as __pageData,g as default};
